36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @Column(name = "possible_duplicate")
86	    private Boolean possibleDuplicate;
87	
88	    @Column(name = "possible_duplicate_of")
89	    private Integer possibleDuplicateOf;
90	
91	    @Column(name = "deleted", nullable = false)
92	    private boolean deleted = false;
93	
94	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
95	    private Set<Pet> pets;
96	
97	    public String getTitle() {
98	        return this.title;
99	    }
100	
101	    public void setTitle(String title) {
102	        this.title = title;
103	    }
104	
105	    /**
106	     * The owner's salutation: the {@link #getTitle() title} followed by a space and the last name
107	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title has
108	     * been supplied.
109	     */
110	    public String getSalutation() {
111	        if (this.title == null || this.title.isEmpty()) {
112	            return this.getLastName();
113	        }
114	        return this.title + " " + this.getLastName();
115	    }
116	
117	    public String getAddress() {
118	        return this.address;
119	    }
120	
121	    public void setAddress(String address) {
122	        this.address = address;
123	    }
124	
125	    public String getAddressLine1() {
126	        return this.addressLine1;
127	    }
128	
129	    public void setAddressLine1(String addressLine1) {
130	        this.addressLine1 = addressLine1;
131	    }
132	
133	    public String getAddressLine2() {
134	        return this.addressLine2;
135	    }
136	
137	    public void setAddressLine2(String addressLine2) {
138	        this.addressLine2 = addressLine2;
139	    }
140	
141	    public String getCity() {
142	        return this.city;
143	    }
144	
145	    public void setCity(String city) {
146	        this.city = city;
147	    }
148	
149	    public String getTelephone() {
150	        return this.telephone;
151	    }
152	
153	    public void setTelephone(String telephone) {
154	        this.telephone = telephone;
155	    }
156	
157	    /**
158	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
159	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
160	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
161	     * been set.
162	     */
163	    public String getTelephoneDisplay() {
164	        return Telephone.forDisplay(this.telephone);
165	    }
166	
167	    public String getEmail() {
168	        return this.email;
169	    }
170	
171	    public void setEmail(String email) {
172	        this.email = email;
173	    }
174	
175	    public String getPostcode() {
176	        return this.postcode;
177	    }
178	
179	    public void setPostcode(String postcode) {
180	        this.postcode = postcode;
181	    }
182	
183	    public LocalDate getRegistrationDate() {
184	        return this.registrationDate;
185	    }
186	
187	    public void setRegistrationDate(LocalDate registrationDate) {
188	        this.registrationDate = registrationDate;
189	    }
190	
191	    public LocalDate getBirthDate() {
192	        return this.birthDate;
193	    }
194	
195	    public void setBirthDate(LocalDate birthDate) {
196	        this.birthDate = birthDate;
197	    }
198	
199	    public String getCustomerCode() {
200	        return this.customerCode;
201	    }
202	
203	    public void setCustomerCode(String customerCode) {
204	        this.customerCode = customerCode;
205	    }
206	
207	    public String getHouseholdId() {
208	        return this.householdId;
209	    }
210	
211	    public void setHouseholdId(String householdId) {
212	        this.householdId = householdId;
213	    }
214	
215	    public Integer getNamesakeCount() {
216	        return this.namesakeCount;
217	    }
218	
219	    public void setNamesakeCount(Integer namesakeCount) {
220	        this.namesakeCount = namesakeCount;
221	    }
222	
223	    public Integer getHouseholdSize() {
224	        return this.householdSize;
225	    }
226	
227	    public void setHouseholdSize(Integer householdSize) {
228	        this.householdSize = householdSize;
229	    }
230	
231	    /**
232	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
233	     * postcode while holding a different telephone. Resolved at creation and stored so it is
234	     * reported consistently on every later read.
235	     */
236	    public Boolean getPossibleDuplicate() {
237	        return this.possibleDuplicate;
238	    }
239	
240	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
241	        this.possibleDuplicate = possibleDuplicate;
242	    }
243	
244	    /**
245	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
246	     * is not a possible duplicate.
247	     */
248	    public Integer getPossibleDuplicateOf() {
249	        return this.possibleDuplicateOf;
250	    }
251	
252	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
253	        this.possibleDuplicateOf = possibleDuplicateOf;
254	    }
255	
256	    /**
257	     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
258	     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
259	     * created owner is never deleted.
260	     */
261	    public boolean isDeleted() {
262	        return this.deleted;
263	    }
264	
265	    public void setDeleted(boolean deleted) {
266	        this.deleted = deleted;
267	    }
268	
269	    /**
270	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
271	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
272	     * email or household contributes an empty string. Two owners are duplicates only when their
273	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
274	     * different telephones have distinct identity keys and are both allowed.
275	     */
276	    public String getIdentityKey() {
277	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
278	    }
279	
280	    private static String orEmpty(String value) {
281	        return value == null ? "" : value;
282	    }
283	
284	    /**
285	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
286	     * last two digits of the {@link #getFiscalYear() fiscal year} of the business-day-adjusted
287	     * registration date (e.g. {@code 'SMI-0007-M27'}). Derived from the owner's own fields;
288	     * absent until both the customer code and registration date have been assigned.
289	     */
290	    public String getMembershipNumber() {
291	        if (this.customerCode == null || this.registrationDate == null) {
292	            return null;
293	        }
294	        return String.format("%s-M%02d", this.customerCode, FiscalYear.endingYear(this.registrationDate) % 100);
295	    }
296	
297	    /**
298	     * The owner's fiscal year, formatted {@code 'FY<YY>'} and derived from the business-day-adjusted
299	     * {@link #getRegistrationDate() registration date}. The fiscal year starts on 1 July; see
300	     * {@link FiscalYear}. Absent until a registration date has been assigned.
301	     */
302	    public String getFiscalYear() {
303	        if (this.registrationDate == null) {
304	            return null;
305	        }
306	        return FiscalYear.label(this.registrationDate);
307	    }
308	
309	    /**
310	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
311	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
312	     */
313	    public Integer getCheckDigit() {
314	        if (this.customerCode == null) {
315	            return null;
316	        }
317	        return Luhn.checkDigit(this.customerCode);
318	    }
319	
320	    /**
321	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July boundaries crossed
322	     * from the {@link #getRegistrationDate() registration date} up to today (see {@link FiscalYear}).
323	     * An owner still in their registration fiscal year has a tenure of zero. Absent until a
324	     * registration date is present.
325	     */
326	    public Long getTenureFiscalYears() {
327	        if (this.registrationDate == null) {
328	            return null;
329	        }
330	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
331	    }
332	
333	    /**
334	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
335	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
336	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
337	     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
338	     * year (the registration and current dates fall in different fiscal years).
339	     */
340	    public Integer getMembershipPoints() {
341	        int points = 0;
342	        boolean hasEmail = this.email != null && !this.email.isEmpty();
343	        if (hasEmail) {
344	            points += 2;
345	        }
346	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
347	        if (unique) {
348	            points += 1;
349	        }
350	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
351	        if (sharedHousehold) {
352	            points += 2;
353	        }
354	        Long tenureFiscalYears = getTenureFiscalYears();
355	        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
356	        if (tenured) {
357	            points += 3;
358	        }
359	        return points;
360	    }
361	
362	    /**
363	     * The owner's membership level, a number from 1 to 4 derived from the owner's
364	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
365	     * 4 for 6 or more.
366	     */
367	    public Integer getMembershipLevel() {
368	        int points = getMembershipPoints();
369	        if (points >= 6) {
370	            return 4;
371	        }
372	        if (points >= 4) {
373	            return 3;
374	        }
375	        if (points >= 2) {
376	            return 2;
377	        }
378	        return 1;
379	    }
380	
381	    /**
382	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
383	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
384	     * before a customer code has been assigned.
385	     */
386	    public String getLocality() {
387	        if (this.customerCode == null) {
388	            return Regions.UNKNOWN;
389	        }
390	        int separator = this.customerCode.indexOf('-');
391	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
392	    }
393	
394	    /**
395	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
396	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
397	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
398	     */
399	    public String getTimezone() {
400	        return Regions.timezoneOf(getLocality());
401	    }
402	
403	    /**
404	     * The owner's preferred contact channel, derived from the owner's own fields:
405	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
406	     */
407	    public String getContactPreference() {
408	        boolean hasEmail = this.email != null && !this.email.isEmpty();
409	        return hasEmail ? "EMAIL" : "PHONE";
410	    }
411	
412	    /**
413	     * The owner's age band, derived from the owner's own fields: the whole years between
414	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
415	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
416	     * (65 or older). Absent until a birth date and a registration date are both present.
417	     */
418	    public String getAgeBand() {
419	        if (this.birthDate == null || this.registrationDate == null) {
420	            return null;
421	        }
422	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
423	        if (age < 18) {
424	            return "MINOR";
425	        }
426	        return age < 65 ? "ADULT" : "SENIOR";
427	    }
428	
429	    /**
430	     * Resolve the effective registration date before persisting: default it to the server's
431	     * current date when none was supplied, then roll it forward off weekends so a newly
432	     * registered owner always has a business-day registration date. Every value derived from it
433	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
434	     * date.
435	     */
436	    @PrePersist
437	    private void resolveRegistrationDate() {
438	        if (this.registrationDate == null) {
439	            this.registrationDate = LocalDate.now();
440	        }
441	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
442	    }
443	
444	    protected Set<Pet> getPetsInternal() {
445	        if (this.pets == null) {
446	            this.pets = new HashSet<>();
447	        }
448	        return this.pets;
449	    }
450	
451	    protected void setPetsInternal(Set<Pet> pets) {
452	        this.pets = pets;
453	    }
454	
455	    public List<Pet> getPets() {
456	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
457	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
458	        return Collections.unmodifiableList(sortedPets);
459	    }
460	
461	    public void setPets(List<Pet> pets) {
462	        this.pets = new HashSet<>(pets);
463	    }
464	
465	    public void addPet(Pet pet) {
466	        getPetsInternal().add(pet);
467	        pet.setOwner(this);
468	    }
469	
470	    /**
471	     * Return the Pet with the given name, or null if none found for this Owner.
472	     *
473	     * @param name to test
474	     * @return true if pet name is already in use
475	     */
476	    public Pet getPet(String name) {
477	        return getPet(name, false);
478	    }
479	
480	    /**
481	     * Return the Pet with the given name, or null if none found for this Owner.
482	     *
483	     * @param name to test
484	     * @return true if pet name is already in use
485	     */
486	    public Pet getPet(String name, boolean ignoreNew) {
487	        name = name.toLowerCase();
488	        for (Pet pet : getPetsInternal()) {
489	            if (!ignoreNew || !pet.isNew()) {
490	                String compName = pet.getName();
491	                compName = compName.toLowerCase();
492	                if (compName.equals(name)) {
493	                    return pet;
494	                }
495	            }
496	        }
497	        return null;
498	    }
499	
500	    public Pet getPet(Integer petId) {
501	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
502	    }
503	
504	    @Override
505	    public String toString() {
506	        return new ToStringCreator(this)
507	
508	            .append("id", this.getId())
509	            .append("new", this.isNew())
510	            .append("lastName", this.getLastName())
511	            .append("firstName", this.getFirstName())
512	            .append("address", this.address)
513	            .append("city", this.city)
514	            .append("telephone", this.telephone)
515	            .append("email", this.email)
516	            .toString();
517	    }
518	}
