54	
55	    /**
56	     * The person's name formatted as {@code "LastName, FirstName"} from the stored names.
57	     */
58	    public String getDisplayName() {
59	        return this.lastName + ", " + this.firstName;
60	    }
61	
62	    /**
63	     * The person's initials: the upper-cased first letters of {@code firstName} and
64	     * {@code lastName}, dot-separated with a trailing dot, e.g. {@code "J.S."}.
